package main

// Writes the content of the distribution repository,
// github.com/potluckdb/potluckdb-go, for one PotluckDB version:
//
//	README.md            what the repository is (generated; never edited)
//	sqlite3/             the driver module, github.com/potluckdb/potluckdb-go/sqlite3
//	lib/<target>/        one module per platform, with its static library
//
// The driver is go/sqlite3 of this repository plus generated files: its
// go.mod, the SQLite headers of the release, and one small file per
// platform that imports that platform's module.

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"text/template"
)

const modulePrefix = "github.com/potluckdb/potluckdb-go"

// The Go version the modules declare; the same as go-sqlite3's.
const goDirective = "1.21"

var versionRE = regexp.MustCompile(`^[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.-]+)?$`)

// Files of go/sqlite3 that are not copied: generated, or for this repo only.
var notCopied = map[string]bool{".gitignore": true, "go.mod": true}

type distOptions struct {
	Version string
	CoreDir string
	Out     string
	GoDir   string   // the go/ folder of this repository
	Targets []target // default: all
}

type distResult struct {
	Cores   []*core
	Skipped map[string]string // target -> why it has no module
}

func writeDist(o distOptions) (*distResult, error) {
	if !versionRE.MatchString(o.Version) {
		return nil, fmt.Errorf("version %q is not like 0.8.0-dev.1", o.Version)
	}
	if o.Targets == nil {
		o.Targets = targets
	}
	cores, skipped, err := loadCores(o.Version, o.CoreDir, o.Targets)
	if err != nil {
		return nil, err
	}
	if err := os.RemoveAll(o.Out); err != nil {
		return nil, err
	}
	d := &dist{distOptions: o, cores: cores, skipped: skipped}
	for _, c := range cores {
		if err := d.writeLib(c); err != nil {
			return nil, err
		}
	}
	if err := d.writeDriver(); err != nil {
		return nil, err
	}
	if err := d.writeRoot(); err != nil {
		return nil, err
	}
	return &distResult{Cores: cores, Skipped: skipped}, nil
}

type dist struct {
	distOptions
	cores   []*core
	skipped map[string]string
}

func (d *dist) write(rel string, data []byte) error {
	p := filepath.Join(d.Out, filepath.FromSlash(rel))
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		return err
	}
	return os.WriteFile(p, data, 0o644)
}

func (d *dist) writeTemplate(rel string, tmpl *template.Template, data any) error {
	var b bytes.Buffer
	if err := tmpl.Execute(&b, data); err != nil {
		return fmt.Errorf("%s: %w", rel, err)
	}
	return d.write(rel, b.Bytes())
}

// versionIdent is the version as part of a Go identifier: 0_8_0_dev_1.
func versionIdent(v string) string {
	return regexp.MustCompile(`[^0-9A-Za-z]`).ReplaceAllString(v, "_")
}

type libData struct {
	*core
	Module, ModVersion, VersionIdent, LDFlags, SHA256, Header string
}

func (d *dist) libData(c *core) libData {
	return libData{
		core:         c,
		Module:       c.Target.Module(modulePrefix),
		ModVersion:   "v" + d.Version,
		VersionIdent: versionIdent(d.Version),
		LDFlags:      strings.Join(append([]string{"${SRCDIR}/libsqlite3.a"}, c.Target.LDFlags...), " "),
		SHA256:       c.sha256(c.Static),
		Header:       generatedHeader,
	}
}

const generatedHeader = "// Code generated by go/tools of github.com/potluckdb/potluckdb. DO NOT EDIT."

func (d *dist) writeLib(c *core) error {
	dir := "lib/" + c.Target.Name + "/"
	data := d.libData(c)
	files := map[string][]byte{
		"go.mod":                  []byte(fmt.Sprintf("module %s\n\ngo %s\n", data.Module, goDirective)),
		"libsqlite3.a":            c.Files[c.Static],
		"LICENSE.txt":             c.Files["LICENSE.txt"],
		"THIRD_PARTY_NOTICES.txt": c.Files["THIRD_PARTY_NOTICES.txt"],
		"BUILD-INFO.json":         c.Files["BUILD-INFO.json"],
	}
	for name, content := range files {
		if err := d.write(dir+name, content); err != nil {
			return err
		}
	}
	if err := d.writeTemplate(dir+"doc.go", libDocTmpl, data); err != nil {
		return err
	}
	return d.writeTemplate(dir+"lib.go", libCgoTmpl, data)
}

var libDocTmpl = template.Must(template.New("").Parse(`{{.Header}}

// Package lib is PotluckDB's build of SQLite {{.SQLite}} for {{.Target.Platform}}
// ({{.Target.GoPlatform}}): a static library that programs using
// github.com/potluckdb/potluckdb-go/sqlite3 link in. Import that package,
// not this one.
//
// libsqlite3.a is {{.Static}} of the core archive
// {{.Target.Archive .Version}} (SHA-256 {{.SHA256}});
// BUILD-INFO.json is the archive's own. The library is under the
// PotluckDB binary licence (LICENSE.txt); the SQLite source code compiled
// into it is in the public domain (THIRD_PARTY_NOTICES.txt).
package lib

// IsVersion{{.VersionIdent}} is used by the driver of the same PotluckDB
// version, so that a driver and a library of different versions never
// build together.
const IsVersion{{.VersionIdent}} = true
`))

var libCgoTmpl = template.Must(template.New("").Parse(`{{.Header}}

//go:build cgo && {{.Target.Constraint}}

package lib

// #cgo LDFLAGS: {{.LDFlags}}
import "C"
`))

func (d *dist) writeDriver() error {
	src := filepath.Join(d.GoDir, "sqlite3")
	entries, err := os.ReadDir(src)
	if err != nil {
		return err
	}
	for _, e := range entries {
		if !e.Type().IsRegular() || notCopied[e.Name()] {
			continue
		}
		data, err := os.ReadFile(filepath.Join(src, e.Name()))
		if err != nil {
			return err
		}
		if err := d.write("sqlite3/"+e.Name(), data); err != nil {
			return err
		}
	}
	first := d.cores[0]
	// The header keeps go-sqlite3's name for it (sqlite3-binding.h), so
	// the driver's sources stay as they are, and a sqlite3.h elsewhere on
	// the include path (CGO_CFLAGS) is never picked by mistake.
	copies := map[string][]byte{
		"sqlite3/sqlite3-binding.h": first.Files["include/sqlite3.h"],
		"sqlite3/potluckdb.h":       first.Files["include/potluckdb.h"],
	}
	for name, from := range map[string]string{
		"sqlite3/README.md":              "README.md",
		"sqlite3/THIRD_PARTY_NOTICES.md": "THIRD_PARTY_NOTICES.md",
		"sqlite3/LICENSE":                "../LICENSE",
	} {
		data, err := os.ReadFile(filepath.Join(d.GoDir, filepath.FromSlash(from)))
		if err != nil {
			return err
		}
		copies[name] = data
	}
	for name, data := range copies {
		if err := d.write(name, data); err != nil {
			return err
		}
	}

	var goMod strings.Builder
	fmt.Fprintf(&goMod, "module %s/sqlite3\n\ngo %s\n\nrequire (\n", modulePrefix, goDirective)
	var constraints []string
	for _, c := range sortedCores(d.cores) {
		data := d.libData(c)
		fmt.Fprintf(&goMod, "\t%s %s\n", data.Module, data.ModVersion)
		if err := d.writeTemplate("sqlite3/potluckdb_lib_"+c.Target.Ident()+".go", driverLibTmpl, data); err != nil {
			return err
		}
		constraints = append(constraints, "!("+c.Target.Constraint+")")
	}
	goMod.WriteString(")\n")
	if err := d.write("sqlite3/go.mod", []byte(goMod.String())); err != nil {
		return err
	}
	var supported []string
	for _, c := range d.cores {
		supported = append(supported, c.Target.GoPlatform)
	}
	return d.writeTemplate("sqlite3/potluckdb_lib_none.go", driverNoneTmpl, map[string]any{
		"Header":     generatedHeader,
		"Constraint": strings.Join(constraints, " && "),
		"Supported":  strings.Join(supported, ", "),
	})
}

func sortedCores(cores []*core) []*core {
	cores = append([]*core(nil), cores...)
	sort.Slice(cores, func(i, j int) bool { return cores[i].Target.Name < cores[j].Target.Name })
	return cores
}

var driverLibTmpl = template.Must(template.New("").Parse(`{{.Header}}

//go:build cgo && {{.Target.Constraint}}

package sqlite3

import lib "{{.Module}}"

// The library module must come from the same PotluckDB release as this
// driver. If this does not compile, go.mod asks for another version of
// {{.Module}}: remove that requirement, or run
// go get github.com/potluckdb/potluckdb-go/sqlite3@{{.ModVersion}}
const _ = lib.IsVersion{{.VersionIdent}}
`))

var driverNoneTmpl = template.Must(template.New("").Parse(`{{.Header}}

//go:build cgo && {{.Constraint}}

package sqlite3

/*
#error "PotluckDB has no SQLite library for this platform. It has one for {{.Supported}}."
*/
import "C"
`))

var rootReadmeTmpl = template.Must(template.New("").Parse(`# PotluckDB for Go

This repository holds the Go modules of PotluckDB {{.Version}} (SQLite
{{.SQLite}}). PotluckDB's release writes it; it is never edited by hand. Its
source is the ` + "`go/`" + ` folder of
[potluckdb/potluckdb](https://github.com/potluckdb/potluckdb/tree/main/go).

**To use it, see [sqlite3/README.md](sqlite3/README.md).** In short: import
` + "`github.com/potluckdb/potluckdb-go/sqlite3`" + ` instead of
` + "`github.com/mattn/go-sqlite3`" + `.

| Module | What |
| --- | --- |
| ` + "`github.com/potluckdb/potluckdb-go/sqlite3`" + ` | The database/sql driver, a drop-in replacement for go-sqlite3. The one to import. |
{{- range .Cores}}
| ` + "`{{.Target.Module $.Prefix}}`" + ` | The SQLite library for {{.Target.Platform}} |
{{- end}}

Each module is tagged ` + "`<folder>/v{{.Version}}`" + `, for example
` + "`sqlite3/v{{.Version}}`" + `. The driver needs every library module of its own
version; Go downloads only the one for the platform it builds for.
{{- if .Skipped}}

Not in this version:
{{range $t, $why := .Skipped}}
- {{$t}}: {{$why}}
{{- end}}
{{- end}}

## Licences

- ` + "`sqlite3/`" + `: Apache-2.0 (` + "`LICENSE`" + `). Parts come from
  go-sqlite3, under the MIT licence (` + "`THIRD_PARTY_NOTICES.md`" + `).
- ` + "`lib/*/`" + `: the PotluckDB library, under the PotluckDB binary licence
  (` + "`LICENSE.txt`" + ` in each). The SQLite source code compiled into it is in
  the public domain (` + "`THIRD_PARTY_NOTICES.txt`" + `).
`))

func (d *dist) writeRoot() error {
	if err := d.write(".gitattributes", []byte("# Every file is kept byte for byte (the modules' checksums depend on it).\n* -text\n")); err != nil {
		return err
	}
	return d.writeTemplate("README.md", rootReadmeTmpl, map[string]any{
		"Version": d.Version,
		"SQLite":  d.cores[0].SQLite,
		"Cores":   sortedCores(d.cores),
		"Prefix":  modulePrefix,
		"Skipped": d.skipped,
	})
}
